/* Online campaign enrollment. Campaigns and gangs retain their canonical local IDs. */
(function(){
'use strict';
const ownerStates=new Map();
let joinState=null,ownerDialog=null,joinRouteActive=false;
const api=(path,options)=>window.AccountParity.api(path,options);
const body=(method,value)=>({method,body:JSON.stringify(value)});
const text=(en,ko,cls='')=>`<span${cls?` class="${cls}"`:''} data-i18n-ko="${esc(ko)}">${esc(en)}</span>`;
const action=(name,en,ko,kind='',extra='')=>`<button type="button" class="btn ${kind}" data-enrollment-action="${name}" ${extra}>${text(en,ko)}</button>`;
const statusLabel=status=>({pending:['Pending approval','승인 대기'],approved:['Approved','승인됨'],rejected:['Rejected','거절됨'],withdrawn:['Withdrawn','취소됨'],removed:['Removed','참가 종료']})[status]||['Not submitted','미신청'];
const status=status=>{const pair=statusLabel(status);return `<span class="enroll-status enroll-status-${esc(status||'none')}">${text(...pair)}</span>`};
const canManage=c=>!!window.MMCampaignPermissions?.canArbitrate(c);
const canPublishBeforeApproval=c=>window.MMCampaignPermissions?.role(c)==='owner';
function assertManager(state){const c=data.campaigns.find(row=>row.id===state.id);if(!state.dialog?.isConnected||window.AccountParity?.account?.id!==state.actorId||data.view!==state.view||data.selectedCampaign!==state.selectedCampaign||!canManage(c)||(c.remoteCampaignId||c.id)!==state.serverId)throw Error(window.UKI18n?.language==='ko'?'캠페인 권한이 변경되었습니다. 모집 설정을 다시 여세요.':'Campaign access changed. Reopen recruitment settings.');return c}
const codeFromPath=()=>{const match=location.pathname.match(/^\/join\/([^/]+)\/?$/);if(!match)return null;try{return decodeURIComponent(match[1])}catch{return ''}};
const ownerPath=id=>'/campaign-enrollments/'+encodeURIComponent(id);
const invitePath=code=>'/campaign-invites/'+encodeURIComponent(code);
const joinURL=code=>location.origin+'/join/'+encodeURIComponent(code);
const signedIn=()=>!!window.AccountParity?.account?.id;
const loginURL=()=>'/account?return_to='+encodeURIComponent(location.pathname+location.search);
const refreshLocale=()=>window.UKI18n?.refresh();
function errorText(error){return error?.message||'Please try again.'}
function showOwnerMessage(state,message,isError=false){state.feedback={message,isError};if(!state.dialog?.isConnected)return;const host=state.dialog.querySelector('[data-enrollment-feedback]');host.className=isError?'enroll-feedback error':'enroll-feedback';host.setAttribute('role',isError?'alert':'status');host.textContent=message;host.hidden=!message;refreshLocale();if(isError)focusOwnerFeedback(state)}
function markOwnerBusy(state,busy){state.busy=busy;if(state.dialog?.isConnected){state.dialog.querySelectorAll('[data-enrollment-action],#enrollment-settings input,#enrollment-settings textarea,#enrollment-settings select').forEach(node=>node.disabled=busy);state.dialog.setAttribute('aria-busy',String(busy))}}
function ownerRows(state){const rows=state.value.requests||[],pending=rows.filter(row=>row.status==='pending');return `<section class="enroll-requests"><div class="enroll-section-heading"><h3>${text('Join requests','참가 신청')}</h3><span class="enroll-count">${pending.length}</span>${action('owner-refresh','Refresh','새로고침','small')}</div>${!rows.length?`<p class="muted">${text('No join requests yet. Share the link to recruit players.','아직 참가 신청이 없습니다. 링크를 공유해 참가자를 모집하세요.')}</p>`:rows.slice().sort((a,b)=>(a.status==='pending'?-1:0)-(b.status==='pending'?-1:0)||String(b.createdAt).localeCompare(String(a.createdAt))).map(row=>`<article class="enroll-request"><div class="enroll-request-heading"><div><strong data-user-text>${esc(row.username)}</strong><p data-user-text>${esc(row.gangName)}</p></div>${status(row.status)}</div>${row.message?`<p class="enroll-user-note" data-user-text>${esc(row.message)}</p>`:''}<small class="muted" data-user-text>${esc(String(row.createdAt||'').slice(0,16).replace('T',' '))}</small>${row.status==='pending'?`<div class="enroll-request-actions">${action('approve','Approve','승인','primary',`data-enrollment-request="${esc(row.id)}"`)}${action('reject','Reject','거절','',`data-enrollment-request="${esc(row.id)}"`)}</div>`:''}</article>`).join('')}</section>`}
const T=(en,ko)=>window.UKI18n?.language==='en'?en:ko;
const isDirect=value=>value?.joinMode==='direct';
const joinActor=()=>window.AccountParity?.account?.id||'';
const joinLive=(state,actor=state.actorId)=>joinState===state&&codeFromPath()===state.code&&joinActor()===actor;
function focusOwnerFeedback(state){const host=state.dialog?.querySelector('[data-enrollment-feedback]');if(!host||host.hidden)return;host.tabIndex=-1;host.focus({preventScroll:true});const footer=host.closest('.enroll-invite-footer')||host;footer.scrollIntoView?.({block:'nearest',behavior:'instant'});}
function renderInviteLink(state){
 const e=state.value.enrollment,active=isDirect(e)&&e.enabled,url=isDirect(e)?joinURL(e.code):'',feedback=state.feedback||{};
 state.dialog.querySelector('.modal-body').innerHTML=`<section class="enroll-invite-manager" data-ux-feedback><div class="enroll-invite-intro"><span class="enroll-status ${active?'enroll-status-approved':''}">${active?text('Invitation link active','초대 링크 사용 중'):text('Invitation link paused','초대 링크 미사용')}</span><h3>${text('Invite players with one link','링크로 플레이어 초대')}</h3><p>${text('Players with this link can sign in and enter as participants. They register their own gang in the lobby. No friend request or separate approval is needed.','링크를 받은 사람은 로그인 후 참가자로 입장하고, 로비에서 자기 갱을 등록합니다. 친구 추가나 별도 승인은 필요하지 않습니다.')}</p></div>${url?`<label class="enroll-invite-url">${text('Invitation link','초대 링크')}<input class="field" data-invite-link-value readonly value="${esc(url)}" aria-label="${esc(T('Campaign invitation link','캠페인 초대 링크'))}" data-user-text></label>`:`<div class="enroll-invite-empty"><p>${text('Create an invitation link to share this campaign.','이 캠페인을 공유할 초대 링크를 만드세요.')}</p>${e.enabled?`<p class="enroll-help">${text('Creating an invitation link replaces the current approval-based recruitment address. Existing requests remain available in recruitment settings.','초대 링크를 만들면 기존 승인형 모집 주소가 교체됩니다. 접수된 신청은 모집 설정에서 계속 확인할 수 있습니다.')}</p>`:''}</div>`}<div class="enroll-invite-capacity">${text('Participant capacity','참가 정원')} <strong>${esc(e.capacityCount??e.accountCount??e.playerCount)} / ${esc(e.maxPlayers)}</strong></div><div class="enroll-invite-footer"><div data-enrollment-feedback data-ux-feedback class="enroll-feedback ${feedback.isError?'error':''}" role="${feedback.isError?'alert':'status'}" ${!feedback.message?'hidden':''}>${esc(feedback.message||'')}</div><div class="actions">${active?`${action('invite-copy','Copy invitation link','초대 링크 복사','primary')}${action('invite-share','Share','공유')}`:action('invite-enable',state.busy&&state.inviteAction==='invite-enable'?'Creating link…':isDirect(e)?'Enable invitation link':'Create invitation link',state.busy&&state.inviteAction==='invite-enable'?'링크 만드는 중…':isDirect(e)?'초대 링크 다시 켜기':'초대 링크 만들기','primary')}${feedback.isError?action('owner-refresh','Load latest link','최신 링크 다시 불러오기'):''}</div></div><details class="enroll-link-options"><summary>${text('Link management','링크 관리')}</summary><p class="enroll-help">${text('Pausing or replacing a link prevents new entries from that address. Existing participants keep their access.','링크를 중지하거나 교체하면 그 주소로 새로 들어올 수 없습니다. 이미 참가한 계정의 접근 권한은 유지됩니다.')}</p><div class="actions">${isDirect(e)?`${active?action('invite-pause','Pause invitation link','초대 링크 중지','small'):''}${action('invite-rotate','Replace invitation link','초대 링크 교체','small')}`:''}${action('invite-advanced','Recruitment & participant settings','모집·참가 설정','small')}</div></details></section>`;
 refreshLocale();markOwnerBusy(state,state.busy);
}
async function copyInviteLink(state){
 assertManager(state);const value=joinURL(state.value.enrollment.code);let copied=false;
 try{if(!navigator.clipboard?.writeText)throw Error('clipboard unavailable');await navigator.clipboard.writeText(value);copied=true;}catch{const field=state.dialog.querySelector('[data-invite-link-value]');field?.focus({preventScroll:true});field?.select();try{copied=!!document.execCommand?.('copy');}catch{}}
 if(state.dialog?.isConnected)showOwnerMessage(state,copied?T('Invitation link copied.','초대 링크를 복사했습니다.'):T('The link is selected. Long-press it or use your device’s Copy command.','링크를 선택했습니다. 길게 누르거나 기기의 복사 기능으로 복사하세요.'));
}
async function inviteLinkAction(state,button){
 const type=button.dataset.enrollmentAction;assertManager(state);
 if(type==='owner-retry'||type==='owner-refresh'){state.feedback=null;showOwnerMessage(state,'');markOwnerBusy(state,true);try{await window.AccountParity.ensureSynced();assertManager(state);await fetchOwner(state);}catch(error){showOwnerMessage(state,errorText(error),true);}finally{markOwnerBusy(state,false);}return;}
 if(type==='invite-copy')return copyInviteLink(state);
 if(type==='invite-share'){
  if(!navigator.share)return copyInviteLink(state);
  try{await navigator.share({title:data.campaigns.find(c=>c.id===state.id)?.name||T('Campaign invitation','캠페인 초대'),text:T('Join our campaign and register your gang in the lobby.','캠페인에 참가하고 로비에서 내 갱을 등록하세요.'),url:joinURL(state.value.enrollment.code)});if(state.dialog.isConnected)showOwnerMessage(state,T('Share window opened.','공유 창을 열었습니다.'));}catch(error){if(error?.name==='AbortError')showOwnerMessage(state,T('Sharing cancelled.','공유를 취소했습니다.'));else await copyInviteLink(state);}return;
 }
 if(type==='invite-advanced'){const id=state.id;closeModal();ownerDialog=null;return openOwner(id);}
 if(type==='invite-rotate'&&!button.dataset.confirm){button.dataset.confirm='yes';button.innerHTML=text('Confirm: replace the old link','확인: 기존 링크 교체');return;}
 if(!['invite-enable','invite-pause','invite-rotate'].includes(type))return fetchOwner(state);
 const e=state.value.enrollment,settings={enabled:type==='invite-enable'?true:type==='invite-pause'?false:!!e.enabled,joinMode:'direct',maxPlayers:e.maxPlayers,description:e.description||'',expectedUpdatedAt:e.updatedAt,expectedCode:e.code,...(type==='invite-rotate'||!isDirect(e)?{rotateCode:true}:{})};
 state.feedback=null;state.inviteAction=type;markOwnerBusy(state,true);renderInviteLink(state);
 try{await window.AccountParity.ensureSynced();assertManager(state);const result=await api(ownerPath(state.serverId),body('PUT',settings));assertManager(state);state.value=result;showOwnerMessage(state,type==='invite-pause'?T('Invitation link paused. Existing participants are unchanged.','초대 링크를 중지했습니다. 기존 참가자는 그대로입니다.'):type==='invite-rotate'?T('A new invitation link is ready. The old address no longer works.','새 초대 링크를 만들었습니다. 이전 주소는 더 이상 사용할 수 없습니다.'):T('Invitation link is ready. Copy or share it below.','초대 링크를 만들었습니다. 아래에서 복사하거나 공유하세요.'));}catch(error){showOwnerMessage(state,errorText(error),true);}finally{state.inviteAction='';markOwnerBusy(state,false);if(state.dialog.isConnected){renderInviteLink(state);if(state.feedback?.isError)focusOwnerFeedback(state);}}
}
async function openInviteLink(id){return openOwner(id,{inviteOnly:true});}
function inviteUnavailable(reason){return ({paused:['This invitation link is paused.','초대 링크가 중지되어 있습니다.'],closed:['This campaign has ended.','종료된 캠페인입니다.'],full:['This campaign is full.','참가 정원이 가득 찼습니다.'],history:['Check your previous participation with the host.','이전 참가 상태를 주최자에게 확인해 주세요.'],removed:['Your previous access has ended. Ask the host for an invitation.','이전 참가 권한이 종료되었습니다. 주최자에게 초대를 요청해 주세요.'],'pending-invitation':['You already have an account invitation. Review it in your account.','이미 받은 계정 초대가 있습니다. 계정에서 해당 초대를 확인해 주세요.']})[reason]||['Campaign participation is unavailable.','현재 캠페인에 참가할 수 없습니다.'];}
function directJoinBody(state){
 const {invite,membership}=state.value,accepted=membership?.status==='accepted',reason=invite.joinUnavailableReason||(!invite.enabled?'paused':Number(invite.capacityCount??invite.accountCount??invite.playerCount)>=Number(invite.maxPlayers)?'full':null),message=reason?inviteUnavailable(reason):null;
 let content='';
 if(accepted)content=`<section class="enroll-direct-join"><span class="enroll-status enroll-status-approved">${text('Campaign participant','캠페인 참가 중')}</span><h2>${text('Continue in the campaign lobby','캠페인 로비로 이동')}</h2><p>${text('Register your own roster in the lobby and challenge other players. Your current account role is kept.','로비에서 본인 로스터의 갱을 등록하고 상대에게 도전하세요. 기존 계정 권한은 유지됩니다.')}</p><div class="enroll-action-footer">${joinFeedback(state)}<div class="actions">${action('open-campaign','Open campaign lobby','캠페인 로비 열기','primary')}${action('join-retry','Refresh status','상태 새로고침')}</div></div></section>`;
 else if(reason||invite.canJoin===false)content=`<section class="enroll-direct-join"><h2>${text(...(message||inviteUnavailable(null)))}</h2><p>${text('Ask the host to check the link or try again later.','주최자에게 링크 상태를 확인하거나 나중에 다시 시도해 주세요.')}</p><div class="enroll-action-footer">${joinFeedback(state)}<div class="actions">${action('join-retry','Check link again','링크 다시 확인')}${reason==='pending-invitation'?`<a class="btn" href="/account">${text('Open account','계정 열기')}</a>`:''}</div></div></section>`;
 else if(!signedIn())content=`<section class="enroll-direct-join"><h2>${text('Join this campaign','이 캠페인에 참가하기')}</h2><p>${text('Sign in or create an account to join. No friend request is required. Choose your gang in the lobby after entering.','로그인하거나 계정을 만들면 참가할 수 있습니다. 친구 추가 없이 입장하고 로비에서 내 갱을 선택하세요.')}</p><div class="enroll-action-footer">${joinFeedback(state)}<div class="actions"><a class="btn primary" href="${esc(loginURL())}" target="_top">${text('Sign in · Create account','로그인 · 회원가입')}</a></div></div></section>`;
 else if(!window.AccountParity.ready)content=`<section class="enroll-direct-join"><p>${text('Connecting your account records…','계정 기록을 연결하는 중입니다…')}</p><div class="enroll-action-footer">${joinFeedback(state)}<div class="actions">${action('join-retry','Retry connection','연결 다시 시도')}</div></div></section>`;
 else content=`<section class="enroll-direct-join"><h2>${text('Join as a campaign participant','캠페인 참가자로 입장')}</h2><p>${text('Enter the campaign now, then register a gang from your own roster in the lobby. You can create a gang there if needed.','캠페인에 입장한 뒤 로비에서 본인 로스터의 갱을 등록하세요. 갱이 없다면 그곳에서 새로 만들 수 있습니다.')}</p><div class="enroll-action-footer">${joinFeedback(state)}<div class="actions">${action('join-direct',state.busy?'Joining…':'Join campaign',state.busy?'캠페인 참가 중…':'캠페인 참가하기','primary')}</div></div></section>`;
 return `<div class="enroll-join-heading"><div class="eyebrow">${text('CAMPAIGN INVITATION','캠페인 초대')}</div><h1 data-user-text>${esc(invite.name)}</h1><p class="enroll-host"><span data-user-text>${esc(invite.ownerName)}</span> · <span data-user-text>${esc(invite.edition)}</span></p><div class="enroll-public-meta"><span>${text('Participant capacity','참가 정원')} <strong>${esc(invite.capacityCount??invite.accountCount??invite.playerCount)} / ${esc(invite.maxPlayers)}</strong></span><span class="enroll-status ${invite.enabled?'enroll-status-approved':''}">${invite.enabled?text('Invitation open','초대 중'):text('Paused','중지됨')}</span></div>${invite.description?`<p class="enroll-public-description" data-user-text>${esc(invite.description)}</p>`:''}</div><div class="enroll-join-content">${content}</div>`;
}
function joinFeedback(state){return `<p class="enroll-feedback ${state.error?'error':''}" data-enrollment-join-feedback data-ux-feedback tabindex="-1" role="${state.error?'alert':'status'}">${esc(state.error||state.notice||'')}</p>`;}
function focusJoinFeedback(){const node=document.querySelector('[data-enrollment-join-feedback]');if(!node?.textContent.trim())return;node.focus({preventScroll:true});(node.closest('.enroll-action-footer')||node).scrollIntoView?.({block:'end',behavior:'instant'});}
async function openJoinedCampaign(state,actor){const id=state.value.invite.campaignId;await window.AccountParity.openShared(id);if(!joinLive(state,actor))return;history.pushState({},'','/campaigns/'+encodeURIComponent(data.selectedCampaign||id));render();}
function renderOwner(state){if(!state.dialog?.isConnected||!state.value)return;if(state.inviteOnly)return renderInviteLink(state);const e=state.value.enrollment;state.dialog.querySelector('.modal-body').innerHTML=`<div class="enroll-manager"><p class="muted">${text('Share a recruitment link, review each request, and admit the gangs you approve.','모집 링크를 공유하고 참가 신청을 확인한 뒤 갱을 승인하세요.')}</p><form id="enrollment-settings" class="enroll-settings"><label class="enroll-toggle"><span>${text('Accept online join requests','온라인 참가 신청 받기')}</span><input type="checkbox" name="enabled" ${e.enabled?'checked':''}></label><label>${text('Join method','참가 방식')}<select class="field" name="joinMode"><option value="direct" data-i18n-en="Join directly with the link" data-i18n-ko="링크로 바로 참가" ${isDirect(e)?'selected':''}>${T('Join directly with the link','링크로 바로 참가')}</option><option value="request" data-i18n-en="Request host approval" data-i18n-ko="신청 후 승인" ${!isDirect(e)?'selected':''}>${T('Request host approval','신청 후 승인')}</option></select><small class="enroll-help">${text('Changing this method replaces the previous link. Existing requests remain.','참가 방식을 바꾸면 기존 링크가 교체됩니다. 접수된 신청은 유지됩니다.')}</small></label><div class="enroll-settings-grid"><label>${text('Player limit','최대 참가 인원')}<input class="field" type="number" name="maxPlayers" min="1" max="100" required value="${esc(e.maxPlayers)}"></label><div class="enroll-capacity"><strong>${esc(e.playerCount)} / ${esc(e.maxPlayers)}</strong>${text('Registered gangs','등록된 갱')}</div></div><label>${text('Public recruitment description','공개 모집 안내')}<textarea class="field" name="description" maxlength="2000" rows="3" data-user-text>${esc(e.description||'')}</textarea></label><p class="enroll-help">${text('Only the campaign name, edition, host, recruitment description and player count are public. Gang details are shown after approval.','캠페인 이름·에디션·주최자·모집 안내·참가 인원만 공개됩니다. 갱 상세 정보는 승인 후 표시됩니다.')}</p><div class="actions">${action('owner-save','Save recruitment settings','모집 설정 저장','primary')}</div></form><section class="enroll-link-section"><h3>${text('Recruitment link','모집 링크')}</h3><div class="enroll-link-row"><a class="enroll-share-link" href="${esc(joinURL(e.code))}" target="_blank" rel="noopener" data-user-text>${esc(joinURL(e.code))}</a>${action('copy','Copy link','링크 복사')}</div>${!e.enabled?`<p class="enroll-help">${text('Recruitment is paused. Enable it above before sharing the link.','현재 모집이 중지되어 있습니다. 위에서 참가 신청을 활성화하세요.')}</p>`:''}<details class="enroll-link-options"><summary>${text('Link options','링크 관리')}</summary><p class="enroll-help">${text('Replacing the link invalidates the old address. Existing requests remain.','링크를 교체하면 기존 주소는 사용할 수 없습니다. 접수된 신청은 유지됩니다.')}</p>${action('rotate','Replace recruitment link','모집 링크 교체','small')}</details></section><div data-enrollment-feedback role="status" class="enroll-feedback"></div>${ownerRows(state)}</div>`;refreshLocale();markOwnerBusy(state,state.busy)}
async function fetchOwner(state){assertManager(state);const result=await api(ownerPath(state.serverId));assertManager(state);state.value=result;renderOwner(state)}
async function openOwner(id,{inviteOnly=false}={}){const c=data.campaigns.find(row=>row.id===id||row.remoteCampaignId===id);if(!canManage(c))return;if(ownerDialog?.isConnected)return;showModal(inviteOnly?text('Campaign invitation link','캠페인 초대 링크'):text('Online Participation','온라인 참가'),`<p class="enroll-loading" role="status">${text('Loading recruitment settings…','모집 설정을 불러오는 중…')}</p>`,'Close',()=>true);const dialog=document.querySelector('.modal-bg'),closeButton=dialog.querySelector('#modal-submit');closeButton.textContent='Close';closeButton.dataset.i18nEn='Close';closeButton.dataset.i18nKo='닫기';refreshLocale();dialog.classList.add('enroll-dialog');if(inviteOnly){dialog.classList.add('enroll-invite-dialog');dialog.dataset.uxFeedback='';}dialog.querySelector('#modal-cancel').hidden=true;ownerDialog=dialog;const state={id:c.id,serverId:c.remoteCampaignId||c.id,actorId:window.AccountParity?.account?.id,view:data.view,selectedCampaign:data.selectedCampaign,dialog,busy:true,value:null,inviteOnly,feedback:null};ownerStates.set(c.id,state);try{if(!signedIn())throw Error('Sign in to manage online recruitment.');await window.AccountParity.ensureSynced();await fetchOwner(state)}catch(error){if(dialog.isConnected){dialog.querySelector('.modal-body').innerHTML=`<div data-enrollment-feedback class="enroll-feedback error" role="alert">${esc(errorText(error))}</div><div class="actions">${!signedIn()?`<a class="btn primary" href="${esc(loginURL())}" target="_top">${text('Sign in · Create account','로그인 · 회원가입')}</a>`:action('owner-retry','Retry','다시 시도')}</div>`;refreshLocale()}}finally{markOwnerBusy(state,false)}}
function ownerDraft(state){const form=state.dialog?.querySelector('#enrollment-settings');if(!form||!form.reportValidity())return null;return {enabled:form.elements.enabled.checked,maxPlayers:Number(form.elements.maxPlayers.value),description:form.elements.description.value,joinMode:form.elements.joinMode?.value||state.value?.enrollment?.joinMode||'request'}}
async function ownerAction(button){const dialog=button.closest('.enroll-dialog'),state=[...ownerStates.values()].find(value=>value.dialog===dialog);if(!state||state.busy)return;try{assertManager(state)}catch(error){showOwnerMessage(state,errorText(error),true);return}const type=button.dataset.enrollmentAction;if(state.inviteOnly)return inviteLinkAction(state,button);if(type==='approve'&&canPublishBeforeApproval(data.campaigns.find(row=>row.id===state.id))&&window.MMRosterValidation?.ensureReviewed){const c=data.campaigns.find(row=>row.id===state.id),ids=new Set((c?.members||[]).map(row=>row.gangId)),unreviewed=data.gangs.filter(g=>ids.has(g.id)&&!g.remoteReadOnly&&(!g.remoteOwnerId||g.remoteOwnerId===window.AccountParity.account?.id)&&window.MMRosterValidation.requiresReview(g));if(unreviewed.length){for(const g of unreviewed)if(!await window.MMRosterValidation.ensureReviewed(g,'campaign-approval'))break;await openOwner(state.id);return}}if(type==='copy'){try{await navigator.clipboard.writeText(joinURL(state.value.enrollment.code));showOwnerMessage(state,window.UKI18n?.t('Link copied.')||'Link copied.')}catch{showOwnerMessage(state,window.UKI18n?.t('Copy the recruitment link shown above.')||'Copy the recruitment link shown above.')}return}if(type==='rotate'&&!button.dataset.confirm){button.dataset.confirm='yes';button.innerHTML=text('Confirm: replace link','확인: 링크 교체');return}const settings=['owner-save','rotate'].includes(type)?ownerDraft(state):null;if(['owner-save','rotate'].includes(type)&&!settings)return;markOwnerBusy(state,true);showOwnerMessage(state,'');try{await window.AccountParity.ensureSynced();assertManager(state);if(type==='owner-save'||type==='rotate'){state.value=await api(ownerPath(state.serverId),body('PUT',{...settings,expectedUpdatedAt:state.value.enrollment.updatedAt,expectedCode:state.value.enrollment.code,...(type==='rotate'?{rotateCode:true}:{})}));renderOwner(state);showOwnerMessage(state,window.UKI18n?.t('Settings saved.')||'Settings saved.')}else if(type==='approve'||type==='reject'){if(type==='approve'&&canPublishBeforeApproval(assertManager(state))){const published=await window.AccountParity.publishCampaign(state.id,{expectedRevision:state.value.enrollment.revision,refresh:false});assertManager(state);state.value.enrollment.revision=published.revision;}await api(ownerPath(state.serverId)+'/requests/'+encodeURIComponent(button.dataset.enrollmentRequest)+'/respond',body('POST',{action:type,revision:state.value.enrollment.revision}));if(type==='approve')await window.AccountParity.refreshShared(state.id,{navigate:false,preserveOwnerEdits:true});await fetchOwner(state);showOwnerMessage(state,window.UKI18n?.t(type==='approve'?'Request approved.':'Request rejected.')||(type==='approve'?'Request approved.':'Request rejected.'))}else await fetchOwner(state)}catch(error){showOwnerMessage(state,errorText(error),true);if(!state.value&&dialog.isConnected&&!dialog.querySelector('[data-enrollment-action="owner-retry"]'))dialog.querySelector('.modal-body').insertAdjacentHTML('beforeend',action('owner-retry','Retry','다시 시도'));}finally{markOwnerBusy(state,false)}}
function eligibleGangs(invite){const uid=window.AccountParity?.account?.id;return (data.gangs||[]).filter(g=>String(g.edition||'').toUpperCase()===String(invite.edition||'').toUpperCase()&&!g.remoteReadOnly&&(!g.remoteOwnerId||g.remoteOwnerId===uid))}
function joinDraft(){const form=document.querySelector('#enrollment-join-form');if(form&&joinState){joinState.draft={gangId:form.elements.gangId.value,message:form.elements.message.value}}}
function joinBody(state){if(state.value&&isDirect(state.value.invite))return directJoinBody(state);if(state.loading&&!state.value)return `<div class="enroll-empty" role="status">${text('Loading campaign…','캠페인을 불러오는 중…')}</div>`;if(!state.value)return `<div class="enroll-empty"><h1>${text('Campaign link unavailable','캠페인 링크를 열 수 없습니다')}</h1><p class="enroll-feedback error" role="alert">${esc(state.error)}</p>${action('join-retry','Retry','다시 시도')}</div>`;const {invite,request}=state.value,gangs=eligibleGangs(invite),limit=Number(invite.maxPlayers),full=Number(invite.playerCount)>=limit;let form='';if(request&&!state.reapply){const pair=statusLabel(request.status);form=`<section class="enroll-join-status"><h2>${text(...pair)}</h2><div class="enroll-request-heading"><strong data-user-text>${esc(request.gangName)}</strong>${status(request.status)}</div>${request.message?`<p class="enroll-user-note" data-user-text>${esc(request.message)}</p>`:''}<p>${request.status==='pending'?text('The host will review your application. Refresh this page to check its status.','주최자가 신청을 확인합니다. 새로고침하여 승인 상태를 확인하세요.'):request.status==='approved'?text('Your gang has joined the campaign. You can now view the shared campaign.','갱이 캠페인에 등록되었습니다. 공유 캠페인을 열어볼 수 있습니다.'):request.status==='withdrawn'?text('You withdrew this request. You may apply again while recruitment is open.','취소한 신청입니다. 모집 중이라면 다시 신청할 수 있습니다.'):request.status==='removed'?text('Your participation has ended. You may apply again while recruitment is open.','캠페인 참가가 종료되었습니다. 모집 중이라면 다시 신청할 수 있습니다.'):text('This application was not accepted. Contact the host if you need more information.','이번 신청은 승인되지 않았습니다. 자세한 내용은 주최자에게 확인하세요.')}</p><div class="actions">${request.status==='pending'?action('withdraw','Withdraw request','신청 취소','danger'):request.status==='approved'?action('open-campaign','Open campaign','캠페인 열기','primary'):invite.canApply&&invite.enabled&&!full?action('apply-again','Apply again','다시 신청','primary'):''}${action('join-retry','Refresh status','상태 새로고침')}</div></section>`}else if(!invite.enabled||full)form=`<div class="enroll-empty"><h2>${full?text('Campaign is full','참가 인원이 마감되었습니다'):text('Recruitment is paused','현재 모집이 중지되었습니다')}</h2><p>${text('Contact the host or check back later.','주최자에게 문의하거나 나중에 다시 확인하세요.')}</p>${action('join-retry','Refresh','새로고침')}</div>`;else if(!invite.canApply)form=`<div class="enroll-empty"><h2>${text('Check your campaign access','캠페인 참여 상태를 확인하세요')}</h2><p>${text('You already own this campaign or have an invitation. Check your account for access.','이미 소유한 캠페인이거나 초대가 있습니다. 계정에서 참여 상태를 확인하세요.')}</p><div class="actions">${(data.campaigns||[]).some(c=>c.id===invite.campaignId)?action('open-campaign','Open campaign','캠페인 열기','primary'):''}<a class="btn" href="/account">${text('Open account','계정 열기')}</a></div></div>`;else if(!signedIn())form=`<section class="enroll-signin"><h2>${text('Bring your gang to the campaign','내 갱으로 캠페인에 참가하기')}</h2><p>${text('Sign in to choose a gang and send a join request to the host.','로그인한 뒤 내 갱을 선택하고 주최자에게 참가 신청을 보내세요.')}</p><a class="btn primary" href="${esc(loginURL())}" target="_top">${text('Sign in · Create account','로그인 · 회원가입')}</a></section>`;else if(!window.AccountParity.ready)form=`<div class="enroll-empty"><p>${text('Your account records are connecting.','저장된 데이터를 불러오는 중입니다.')}</p>${action('join-retry','Retry connection','연결 다시 시도')}</div>`;else if(!gangs.length)form=`<div class="enroll-empty"><h2>${text('Create a compatible gang first','같은 에디션의 갱이 필요합니다')}</h2><p>${text('You need your own synced gang in this campaign’s edition to apply.','이 캠페인과 같은 에디션으로 만든 본인 갱을 계정에 저장한 뒤 신청하세요.')}</p><a class="btn primary" href="/">${text('Go to my gangs','내 갱으로 이동')}</a>${action('join-retry','Refresh gangs','갱 목록 새로고침')}</div>`;else form=`<form id="enrollment-join-form" class="enroll-join-form"><h2>${text('Request to join','참가 신청')}</h2><label>${text('Your gang','참가할 내 갱')}<select class="field" name="gangId" required>${gangs.map(g=>`<option value="${esc(g.id)}" ${state.draft.gangId===g.id?'selected':''} data-user-text>${esc(g.name)}</option>`).join('')}</select></label><label>${text('Message to the host (optional)','주최자에게 남길 말 (선택)')}<textarea class="field" name="message" maxlength="1000" rows="3" data-user-text>${esc(state.draft.message||'')}</textarea></label><p class="enroll-help">${text('Your gang name, roster and this message are shared with the host. Approval gives you access to view the campaign. If you change your gang while waiting, withdraw and apply again.','갱 이름·명단·메시지가 주최자에게 공유됩니다. 승인되면 캠페인을 열람할 수 있습니다. 대기 중 갱을 변경했다면 신청을 취소하고 다시 신청하세요.')}</p><button type="submit" class="btn primary" data-enrollment-action="join-submit">${text('Send join request','참가 신청 보내기')}</button></form>`;return `<div class="enroll-join-heading"><div class="eyebrow">${text('CAMPAIGN RECRUITMENT','캠페인 모집')}</div><h1 data-user-text>${esc(invite.name)}</h1><p class="enroll-host"><span data-user-text>${esc(invite.ownerName)}</span> · <span data-user-text>${esc(invite.edition)}</span></p><div class="enroll-public-meta"><span>${text('Registered gangs','등록된 갱')} <strong>${esc(invite.playerCount)} / ${esc(invite.maxPlayers)}</strong></span><span class="enroll-status ${invite.enabled?'enroll-status-approved':''}">${invite.enabled?text('Recruiting','모집 중'):text('Paused','모집 중지')}</span></div>${invite.description?`<p class="enroll-public-description" data-user-text>${esc(invite.description)}</p>`:''}</div><div class="enroll-join-content">${form}<p class="enroll-feedback ${state.error?'error':''}" data-enrollment-join-feedback role="${state.error?'alert':'status'}">${esc(state.error||state.notice||'')}</p></div>`}
function renderJoin(){const code=codeFromPath();let reset=false;if(code===null){joinRouteActive=false;return false}if(!joinState||joinState.code!==code||joinState.actorId!==joinActor()){joinState={code,actorId:joinActor(),joinOperation:'invite-join:'+code+':'+(window.crypto?.randomUUID?.()||id()),loading:false,busy:false,value:null,error:'',notice:'',draft:{gangId:'',message:''}};reset=true;queueMicrotask(()=>loadJoin(joinState))}else if(!joinRouteActive)queueMicrotask(()=>loadJoin(joinState));joinRouteActive=true;if(!reset)joinDraft();const state=joinState,active=document.activeElement,selection=active?.closest('#enrollment-join-form')?{name:active.name,start:active.selectionStart,end:active.selectionEnd}:null;document.querySelector('#app').innerHTML=`<div class="enroll-public-shell"><header class="enroll-public-header"><a class="enroll-public-brand" href="/"><img src="/brand/underhive-korea-192.png" width="44" height="44" alt=""><span>${text('Underhive Korea','언더하이브 코리아')}</span></a><div class="uk-language-switch" role="group" aria-label="Language"><button type="button" data-uk-locale-toggle="ko" aria-pressed="${window.UKI18n?.language!=='en'}">한</button><button type="button" data-uk-locale-toggle="en" aria-pressed="${window.UKI18n?.language==='en'}">EN</button></div></header><main class="enroll-public-main"><article class="enroll-public-card" data-ux-feedback aria-busy="${state.busy||state.loading}">${joinBody(state)}</article><a class="enroll-home-link" href="/">${text('Back to my workspace','내 작업 공간으로 돌아가기')} →</a></main></div>`;document.querySelectorAll('.enroll-public-card [data-enrollment-action],#enrollment-join-form input,#enrollment-join-form select,#enrollment-join-form textarea').forEach(node=>node.disabled=state.busy||state.loading);refreshLocale();if(selection){const replacement=document.querySelector(`#enrollment-join-form [name="${selection.name}"]`);if(replacement&&!replacement.disabled){replacement.focus({preventScroll:true});if(selection.start!==null&&replacement.setSelectionRange)replacement.setSelectionRange(selection.start,selection.end)}}return true}
async function loadJoin(state){if(state.loading)return;state.loading=true;state.error='';if(codeFromPath()===state.code)renderJoin();try{const value=await api(invitePath(state.code));if(!joinLive(state))return;state.value=value;state.reapply=false}catch(error){if(!joinLive(state))return;state.error=errorText(error)}finally{state.loading=false;if(joinState===state&&codeFromPath()===state.code)renderJoin()}}
async function joinAction(type){
 const state=joinState;if(!state||state.busy||state.loading)return;const actor=joinActor();if(!joinLive(state,actor))return;joinDraft();
 if(type==='apply-again'){state.reapply=true;state.error='';renderJoin();return;}
 if(type==='join-submit'){const form=document.querySelector('#enrollment-join-form');if(!form||!form.reportValidity())return;const selected=data.gangs.find(g=>g.id===state.draft.gangId);if(window.MMRosterValidation?.ensureReviewed){state.busy=true;let checked;try{checked=await window.MMRosterValidation.ensureReviewed(selected,'campaign-enrollment')}finally{state.busy=false}if(!checked||!joinLive(state,actor)){if(joinLive(state,actor))renderJoin();return;}}}
 state.busy=true;state.error='';renderJoin();try{
  if(type==='join-direct'){await window.AccountParity.ensureSynced();if(!joinLive(state,actor))return;const result=await api(invitePath(state.code)+'/join',body('POST',{operationKey:state.joinOperation}));if(!joinLive(state,actor))return;state.value.membership={role:result.role||'viewer',status:'accepted'};state.value.invite.canJoin=false;state.notice=T('You joined the campaign. Open the lobby to register your gang.','캠페인에 참가했습니다. 로비에서 내 갱을 등록하세요.');try{await openJoinedCampaign(state,actor);}catch(error){if(joinLive(state,actor))state.error=T('You joined successfully, but the lobby could not open. Try Open campaign lobby again. ','참가는 완료됐지만 로비를 열지 못했습니다. 캠페인 로비 열기를 다시 눌러 주세요. ')+errorText(error);}}
  else if(type==='join-submit'){await window.AccountParity.ensureSynced();if(!joinLive(state,actor))return;const result=await api(invitePath(state.code)+'/requests',body('POST',{gangId:state.draft.gangId,message:state.draft.message}));if(!joinLive(state,actor))return;state.value.request=result.request;state.reapply=false;state.notice='';}
  else if(type==='withdraw'){await api(invitePath(state.code)+'/requests',{method:'DELETE'});if(!joinLive(state,actor))return;state.value.request=null;state.notice='';await loadJoin(state);}
  else if(type==='open-campaign'){await openJoinedCampaign(state,actor);return;}
  else{if(signedIn()&&!window.AccountParity.ready)await window.AccountParity.ensureSynced();if(!joinLive(state,actor))return;await loadJoin(state);}
 }catch(error){if(joinLive(state,actor))state.error=errorText(error);}finally{state.busy=false;if(joinLive(state,actor)){renderJoin();if(state.error)focusJoinFeedback();}}
}

const previousRender=render;render=function(...args){if(renderJoin())return;const result=previousRender.apply(this,args);const c=typeof campaign==='function'?campaign():null;if(data.view==='campaign'&&canManage(c)&&!['session-detail','report-detail'].includes(data.campaignTab)){if(!document.querySelector('[data-enrollment-open]')){const controls=`<div class="actions enroll-campaign-actions"><button type="button" class="btn small enroll-open" data-enrollment-open="${esc(c.id)}">${text('Online Participation','온라인 참가')}</button></div>`;const card=document.querySelector('.entity-card'),content=document.querySelector('.content');if(card)card.querySelector('.entity-head').insertAdjacentHTML('afterend',controls);else content?.insertAdjacentHTML('afterbegin',controls)}refreshLocale()}return result};
document.addEventListener('click',event=>{const button=event.target.closest?.('[data-enrollment-open],[data-enrollment-action]');if(!button)return;event.preventDefault();if(button.disabled)return;if(button.dataset.enrollmentOpen){openOwner(button.dataset.enrollmentOpen);return}if(button.closest('.enroll-dialog'))ownerAction(button);else joinAction(button.dataset.enrollmentAction)});
document.addEventListener('submit',event=>{if(event.target.id==='enrollment-join-form'){event.preventDefault();joinAction('join-submit')}else if(event.target.id==='enrollment-settings'){event.preventDefault();const button=event.target.querySelector('[data-enrollment-action="owner-save"]');if(button)ownerAction(button)}});
document.addEventListener('input',event=>{if(event.target.closest?.('#enrollment-join-form'))joinDraft()});document.addEventListener('change',event=>{if(event.target.closest?.('#enrollment-join-form'))joinDraft()});
window.addEventListener('uk:languagechange',()=>{if(codeFromPath()!==null)renderJoin()});
window.CampaignEnrollment={open:openOwner,openInviteLink,refresh:()=>joinState?loadJoin(joinState):Promise.resolve(),isJoinRoute:()=>codeFromPath()!==null};
})();
